import os
matches=[]
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            cmd=f.read().replace(b'\x00', b' ').decode('utf-8','ignore')
        if 'pip' in cmd or 'whisper' in cmd:
            matches.append((pid,cmd))
    except Exception:
        pass
print('\n'.join(f"{pid} {cmd}" for pid,cmd in matches) or 'no matches')
PY"}

